         if !addr.is_aligned(PAGE_ALIGNMENT)? {
             return Err(Error::new(ErrorCode::BadAddress, "unaligned virtual address"));
         }

         Ok(Self(addr))
     }

     pub fn into_inner(self) -> T {
         self.0
     }
 }

